#pragma once
// Included with the application's existing functional-group and text APIs.
struct CatalyticMetal {
    std::string element="Pd",oxidation="II",ligands="Ln,X,R1";int numerals=0,format=0;bool excited=false,collapsed=false;
    static std::string attr(const char* name){return std::string("pst.attr.MoleculeStudioCatalytic")+name;}
    static int number(std::string s){if(s.empty())return 999;bool neg=s[0]=='-';if(neg||s[0]=='+')s.erase(s.begin());const char* roman[]={"0","I","II","III","IV","V","VI","VII","VIII","IX","X","XI","XII"};for(int i=0;i<13;++i)if(s==roman[i]||s==std::to_string(i))return neg?-i:i;return 999;}
    std::string state()const{if(oxidation.empty())return "";int n=number(oxidation);if(n==999)return oxidation;const char* r[]={"0","I","II","III","IV","V","VI","VII","VIII","IX","X","XI","XII"};return numerals?std::to_string(n):(n<0?"-":"")+std::string(r[std::abs(n)]);}
    std::vector<std::string> labels()const{std::vector<std::string> out;std::istringstream in(ligands);std::string s;while(std::getline(in,s,',')){auto a=s.find_first_not_of(" \t"),b=s.find_last_not_of(" \t");if(a!=std::string::npos)out.push_back(s.substr(a,b-a+1));}return out;}
    std::string validate()const{if(!elementNumber(element)||!studio::metal_labels::find(element).valid())return "请输入金属元素，如 Pd、Ni、Cu。";if(!oxidation.empty()&&number(oxidation)==999)return "氧化态请输入 -XII 到 XII，或 -12 到 12；激发态请勾选 *。";if(labels().size()>8)return "最多支持 8 个末端配体。";return "";}
    std::vector<TextRun> runs(const Document& d,const std::string& suffix="")const{TextRun r;r.utf8=element;r.fontName=d.defaultFont();r.size=d.defaultTextSize();std::vector<TextRun> out{r};auto st=state();if(!st.empty()){r.utf8=(format==0||format==2)?"("+st+")":st;r.flags=format<2?kSuperscript:0;out.push_back(r);}if(excited){r.utf8="*";r.flags=kSuperscript;out.push_back(r);}if(!suffix.empty()){r.utf8=suffix;r.flags=kFormula;out.push_back(r);}return studio::metal_labels::scripted(out);}
    void remember(Document& d,ObjectId id)const{auto& b=d.extensions(ObjectRef(ObjectKind::Atom,id));b.set(attr("Metal"),"1");b.set(attr("Oxidation"),oxidation);b.set(attr("Ligands"),ligands);b.set(attr("Numerals"),std::to_string(numerals));b.set(attr("Format"),std::to_string(format));b.set(attr("Excited"),excited?"1":"0");b.set("studio.catalytic.oxidation",oxidation);}
    static CatalyticMetal read(const Document& d,ObjectId id){CatalyticMetal c;if(id==kInvalidObjectId)return c;auto a=d.atoms().alive(id);c.element=elementSymbol(a->element);auto& b=d.extensions(ObjectRef(ObjectKind::Atom,id));auto get=[&](const char* k,std::string fallback){auto v=b.findValue(attr(k));return v?*v:fallback;};c.oxidation=get("Oxidation","");if(!b.findValue(attr("Oxidation"))){auto text=d.atomLabel(id);auto start=text.find('('),end=text.find(')',start);if(start!=std::string::npos&&end!=std::string::npos)c.oxidation=text.substr(start+1,end-start-1);}
        c.ligands="";for(auto n:d.neighbours(id))if(d.incidentBonds(n).size()==1){if(!c.ligands.empty())c.ligands+=",";auto text=d.atomLabel(n);c.ligands+=text.empty()?elementSymbol(d.atoms().alive(n)->element):text;}if(b.findValue("studio.compound.fragment"))c.ligands=get("Ligands",c.ligands);c.numerals=std::atoi(get("Numerals","0").c_str());c.format=std::atoi(get("Format","0").c_str());c.excited=get("Excited","0")=="1";c.collapsed=b.findValue("studio.compound.fragment")!=nullptr;return c;}
    static bool fold(Document& d,ObjectId id,bool expand){auto& bag=d.extensions(ObjectRef(ObjectKind::Atom,id));if(!bag.findValue(attr("Metal")))return false;bool compact=bag.findValue("studio.compound.fragment")!=nullptr;
        if(expand){if(!compact)return false;auto p=functional_groups::prepareExpansion(d,id);std::vector<ObjectRef> made;functional_groups::applyExpansion(d,p,made);return true;}
        if(compact||d.incidentBonds(id).empty())return false;auto cfg=read(d,id);Session subset;std::vector<ObjectRef> made;auto e=studioio::append(d,subset.doc,studio::catalytic::component(d,id),Vec2(),&made);if(!e.ok())throw std::runtime_error(e.message);std::ostringstream bytes;e=persistence::writeCdxml(subset.doc,bytes);if(!e.ok())throw std::runtime_error(e.message);tinyxml2::XMLDocument xml;xml.Parse(bytes.str().c_str());auto page=xml.RootElement()->FirstChildElement("page");std::string fragments;for(auto f=page->FirstChildElement("fragment");f;f=f->NextSiblingElement("fragment")){tinyxml2::XMLPrinter out;f->Accept(&out);fragments+=out.CStr();}
        std::set<ObjectId> atoms;for(auto r:studio::catalytic::component(d,id))if(r.kind==ObjectKind::Atom)atoms.insert(r.id);std::string suffix;for(auto label:cfg.labels())suffix+="("+label+")";std::string label;for(auto r:cfg.runs(d,suffix))label+=r.utf8;functional_groups::collapse(d,functional_groups::Match(label,fragments,id,atoms,true));d.setElement(id,elementNumber(cfg.element));cfg.remember(d,id);auto runs=cfg.runs(d,suffix);studioatom::set(d,id,runs);return true;
    }
    ObjectId apply(Document& d,ObjectId id,Vec2 pos)const{auto error=validate();if(!error.empty())throw std::runtime_error(error);if(id==kInvalidObjectId){auto e=d.addAtom(pos,elementNumber(element),&id);if(!e.ok())throw std::runtime_error(e.message);}else if(d.extensions(ObjectRef(ObjectKind::Atom,id)).findValue("studio.compound.fragment"))fold(d,id,true);
        std::vector<ObjectId> terminal;for(auto n:d.neighbours(id))if(d.incidentBonds(n).size()==1)terminal.push_back(n);auto ls=labels();d.setElement(id,elementNumber(element));auto sem=d.atoms().alive(id)->semantics;sem.nodeType=uint8_t(NodeType::Element);sem.implicitHydrogens=0;sem.showLabel=true;d.setAtomSemantics(id,sem);auto rs=runs(d);std::string text;for(auto r:rs)text+=r.utf8;d.setAtomLabel(id,text);studioatom::set(d,id,rs);remember(d,id);
        for(size_t i=ls.size();i<terminal.size();++i){for(auto b:d.incidentBonds(terminal[i]))d.removeObject(ObjectRef(ObjectKind::Bond,b));d.removeAtom(terminal[i]);}
        for(size_t i=0;i<ls.size();++i){ObjectId atom;if(i<terminal.size())atom=terminal[i];else{auto p=d.atoms().alive(id)->position+core::direction(90-i*360./std::max(size_t(3),ls.size()))*d.defaultBondLength();auto e=d.addAtom(p,6,&atom);if(e.ok())e=d.addBond(id,atom,nullptr);if(!e.ok())throw std::runtime_error(e.message);}int z=elementNumber(ls[i]);d.setElement(atom,z?z:6);auto v=d.atoms().alive(atom)->semantics;v.nodeType=uint8_t(z?NodeType::Element:NodeType::Query);v.implicitHydrogens=0;v.showLabel=true;d.setAtomSemantics(atom,v);d.setAtomLabel(atom,ls[i]);TextRun r;r.utf8=ls[i];r.fontName=d.defaultFont();r.size=d.defaultTextSize();r.flags=kFormula;studioatom::set(d,atom,studio::metal_labels::scripted({r}));}
        if(collapsed)fold(d,id,false);return id;
    }
};
